import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';

const ComplaintList = () => {
  const [complaints, setComplaints] = useState([]);

  useEffect(() => {
    fetchComplaints();
  }, []);

  const fetchComplaints = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/complaints');
      setComplaints(response.data);
    } catch (err) {
      console.error(err);
    }
  };

  const updateComplaintStatus = async (id, status) => {
    try {
      await axios.put(`http://localhost:5000/api/complaints/${id}`, { status });
      fetchComplaints();
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div>
      <Link to="/add-complaint">
        <button className="add-btn">Add Complaint</button>
      </Link>
      <table>
        <thead>
          <tr>
            <th>Resident Name</th>
            <th>Description</th>
            <th>Status</th>
            <th>Date</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {complaints.map((complaint) => (
            <tr key={complaint._id}>
              <td>{complaint.residentId ? complaint.residentId.name : 'N/A'}</td>
              <td>{complaint.description}</td>
              <td>{complaint.status}</td>
              <td>{new Date(complaint.createdAt).toLocaleDateString()}</td>
              <td>
                <button
                  className="update-btn"
                  onClick={() => updateComplaintStatus(complaint._id, complaint.status === 'Pending' ? 'Resolved' : 'Pending')}
                >
                  Toggle Status
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default ComplaintList;
